 dict(id='dict_missing',function='get_config_value',source='def get_config_value(config, key):\n    return config[key]\n',spec='Return the dictionary value for key, or None if key is missing.',visible=['assert get_config_value({"a":1},"b") is None','assert get_config_value({"a":1},"a") == 1'],hidden=['assert get_config_value({},"x") is None','assert get_config_value({"x":0},"x") == 0','assert get_config_value({"x":False},"x") is False']),
 dict(id='list_index',function='safe_item',source='def safe_item(items, index):\n    return items[index]\n',spec='Return element at index if index is within [0,len(items)); otherwise return None. Negative indices are invalid.',visible=['assert safe_item([1,2],5) is None','assert safe_item([1,2],1) == 2'],hidden=['assert safe_item([1,2],-1) is None','assert safe_item([],0) is None','assert safe_item([4],0) == 4']),
 dict(id='average_empty',function='average',source='def average(values):\n    return sum(values) / len(values)\n',spec='Return arithmetic mean of a list of numbers, or 0.0 for an empty list.',visible=['assert average([]) == 0.0','assert average([2,4]) == 3.0'],hidden=['assert average([-3,3]) == 0.0','assert average([5]) == 5.0','assert average([1,2,3]) == 2.0']),
