 dict(id='off_by_one',function='sum_to_n',source='def sum_to_n(n):\n    return sum(range(n))\n',spec='For nonnegative integer n return 1+2+...+n (inclusive); n=0 returns 0.',visible=['assert sum_to_n(3) == 6','assert sum_to_n(0) == 0'],hidden=['assert sum_to_n(1) == 1','assert sum_to_n(10) == 55','assert sum_to_n(5) == 15']),
