 dict(id='unique_order',function='unique_values',source='def unique_values(values):\n    return list(set(values))\n',spec='Remove duplicates from a list while preserving the first-occurrence order.',visible=['assert unique_values([3,1,3,2]) == [3,1,2]'],hidden=['assert unique_values([]) == []','assert unique_values(["b","a","b"]) == ["b","a"]','assert unique_values([1,1,2,1]) == [1,2]']),
